#!/usr/bin/env python3
"""Independent bitwise IEEE oracle and canonical row identities; no timing."""
import hashlib
import json
from pathlib import Path
import random
import struct

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[2]


def raw_crc(seed, data):
    state = seed
    for byte in data:
        state ^= byte
        for _ in range(8):
            state = (state >> 1) ^ (0xedb88320 if state & 1 else 0)
    return state


def main():
    # Every row is generated by the complete bitwise message oracle, rather
    # than the candidate's table-to-table zero-byte recurrence.
    rows = [[raw_crc(0, bytes([byte]) + bytes(index)) for byte in range(256)]
            for index in range(24)]

    def flat(seed, data):
        value = 0
        for index, byte in enumerate(data):
            first_seed_byte = (seed >> (index * 8)) & 255 if index < 4 else 0
            value ^= rows[len(data) - 1 - index][byte ^ first_seed_byte]
        return value

    cases = 0
    basis = 0
    rng = random.Random(0x666c617463726331)
    for length in (20, 24):
        for bit in range(length * 8):
            message = bytearray(length)
            message[bit // 8] = 1 << (bit % 8)
            assert flat(0, message) == raw_crc(0, message)
            cases += 1
            basis += 1
        for bit in range(32):
            seed = 1 << bit
            assert flat(seed, bytes(length)) == raw_crc(seed, bytes(length))
            cases += 1
            basis += 1
        for _ in range(10000):
            seed = rng.getrandbits(32)
            message = rng.randbytes(length)
            assert flat(seed, message) == raw_crc(seed, message)
            cases += 1
    source = ROOT / ".zig-cache/crc-flat-segments/candidate/src"
    report = {
        "reproduction_script": "independent_math.py",
        "script_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "cases": cases, "message_and_full_seed_basis_cases": basis,
        "random_cases": 20000,
        "rows": [{"index": index, "bytes": 1024,
                  "little_endian_sha256": hashlib.sha256(struct.pack("<256I", *row)).hexdigest()}
                 for index, row in enumerate(rows)],
        "row_generation": "raw bitwise IEEE CRC of single byte followed by index zero bytes; no candidate recurrence",
        "candidate_source_sha256": {name: hashlib.sha256((source / name).read_bytes()).hexdigest()
                                    for name in ("platform/crc32.zig", "journal/format.zig")},
        "scope": "Independent formula proof and canonical row identities; not Zig execution, alignment/bounds, codegen or performance qualification",
    }
    (HERE / "independent-math.json").write_text(json.dumps(report, indent=2) + "\n")
    print(f"{cases} independent formula cases; {len(rows)} canonical 1KiB row identities")


if __name__ == "__main__":
    main()
